import "server-only";
import type { Prisma } from "@/generated/prisma/client";
import { db } from "@/lib/db";

export async function readAccountNotices(
  userId: string,
  tx?: Prisma.TransactionClient,
) {
  const notices = await (tx ?? db).accountNotice.findMany({
    where: { userId, dismissedAt: null },
    orderBy: [{ createdAt: "asc" }, { id: "asc" }],
    take: 50,
    select: {
      id: true,
      campaignIdSnapshot: true,
      reasonCode: true,
      cancelledCount: true,
      createdAt: true,
    },
  });
  return notices.map((notice) => ({
    ...notice,
    createdAt: notice.createdAt.toISOString(),
  }));
}
export async function dismissAccountNotice(userId: string, noticeId: string) {
  await db.accountNotice.updateMany({
    where: { id: noticeId, userId, dismissedAt: null },
    data: { dismissedAt: new Date() },
  });
}
